const groups=[['preterm','早產兒','Preterm'],['neonate','新生兒','Neonate'],['infant','嬰兒','Infant'],['child','兒童','Child']];
const categories=[{name:'呼吸道',en:'AIRWAY',items:[['氣管內管','Endotracheal tube','口管／鼻管 · 有／無氣囊',['管徑（內徑 mm）','口管深度（cm）','鼻管深度（cm）','估算依據與適用條件']],['喉頭鏡','Laryngoscope','鏡片型式與尺寸',['鏡片型式','鏡片號數']],['喉頭罩','Laryngeal mask airway','依器材廠牌與體重選擇',['廠牌／型號','尺寸與適用體重']],['鼻咽呼吸道','Nasopharyngeal airway','Nasal airway',['內徑／尺寸','長度與選擇依據']],['口咽呼吸道','Oropharyngeal airway','Oral airway',['尺寸','量測與選擇依據']]]},{name:'麻醉藥物',en:'ANESTHESIA',items:['Propofol','Ketamine','Midazolam','Succinylcholine','Cisatracurium (Nimbex)','Rocuronium','Fentanyl','Morphine','Propacetamol (Acetamol)','Sugammadex'].map(n=>[n,'','用途與年齡限制待核對',['適應症／途徑','每公斤劑量與單位','依體重計算結果','最高劑量／限制']])},{name:'急救藥物',en:'RESUSCITATION',items:['Atropine','Epinephrine (Bosmin)','Dobutamine','Dopamine','Sodium bicarbonate','Calcium gluconate','Amiodarone','Adenosine','Norepinephrine','Dextrose','Magnesium sulfate'].map(n=>[n,'','候選項目 · 適應情境與使用方式待核對',['適應情境／途徑','Bolus 劑量／給藥速度','Infusion 劑量與單位','原液／稀釋液／最終濃度','抽取量與最終體積','輸注速率（mL/hr）']])},{name:'輸血',en:'TRANSFUSION',items:[['紅血球濃厚液','Packed red blood cells'],['新鮮冷凍血漿','Fresh frozen plasma'],['血小板','Platelets'],['冷凍沉澱品','Cryoprecipitate']].map(([a,b])=>[a,b,'血品規格與適用條件待核對',['適應情境／血品規格','建議量與計算單位','計算結果','輸注時間／速率','監測與特殊條件']])}];
categories[2].items.push(...['Isoproterenol','Milrinone'].map(n=>[n,'','參考資料已提供；此藥換算內容尚待逐項核對',['適應情境／年齡限制','Bolus／loading dose（是否適用待核對）','Infusion 劑量與單位','原液／稀釋液／最終濃度','抽取量與最終體積','輸注速率（mL/hr）']]));
categories[3].name='輸液與輸血';
categories[3].en='FLUIDS / BLOOD';
categories[3].items.unshift(
 ['維持輸液','Maintenance fluids','維持需求與液體組成待核對',['適用條件／液體種類','每公斤計算公式','每小時速率（mL/hr）','每日總量（mL/day）','葡萄糖／電解質與監測']],
 ['輸液補充／快速輸注','Fluid bolus','適應情境、液體選擇與重新評估條件待核對',['適應情境／液體種類','每次補充量（mL/kg）','依體重計算體積（mL）','輸注時間／速率','重新評估與停止條件']],
 ['缺損與持續流失補充','Deficit & ongoing losses','缺損評估與補充方式待核對',['缺損／流失類型','所需額外輸入資料','補充液體與計算依據','補充量與時間','監測與特殊條件']]
);
let patient=null;
let group='child',category=0,applied=null,onlyFavorites=false;const favorites=new Set(),opened=new Set();const $=s=>document.querySelector(s);
function el(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n}
function field(id,label,unit,min,max,placeholder){const wrap=el('div');const l=el('label','',label);l.htmlFor=id;l.append(el('span','',unit));const i=el('input');Object.assign(i,{id,type:'number',min:String(min),max:String(max),step:'1',placeholder,required:true});i.inputMode='numeric';wrap.append(l,i);return wrap}
function ageFields(){const a=$('#age-fields');a.replaceChildren();if(group==='preterm'){a.append(field('gestation','出生胎齡','週',1,36,'週'),field('gestation-days','另加天數','天',0,6,'0–6'),field('days','出生後日齡','天',0,365,'天'),el('p','field-note','胎齡與出生後日齡分別記錄，不互相替代。'));}else if(group==='neonate')a.append(field('days','出生後日齡','天',0,28,'天'),el('p','field-note','分類目前用於切換輸入欄位；臨床年齡界線待來源確認。'));else if(group==='infant')a.append(field('months','月齡','個月',0,11,'0–11'),field('extra-days','另加天數','天',0,30,'0–30'));else a.append(field('years','年齡','歲',1,18,'歲'),field('months','另加月數','個月',0,11,'0–11'));}
function markDirty(){patient=null;applied=null;$('#summary').textContent='資料已變更，請重新套用';$('#summary').className='summary';$('#error').textContent='';renderResults()}
function renderGroups(){const node=$('#groups');node.replaceChildren();groups.forEach(([id,name,en])=>{const b=el('button',id===group?'active':'',name);b.type='button';b.setAttribute('aria-pressed',String(id===group));b.append(el('small','',en));b.onclick=()=>{group=id;ageFields();renderGroups();markDirty()};node.append(b)})}
function renderTabs(){const node=$('#tabs');node.replaceChildren();categories.forEach((c,i)=>{const b=el('button',i===category?'active':'');b.role='tab';b.id='tab-'+i;b.setAttribute('aria-selected',String(i===category));b.setAttribute('aria-controls','results');b.append(el('span','',c.en),el('b','',c.name));b.onclick=()=>{category=i;$('#search').value='';renderTabs();renderResults()};b.onkeydown=e=>{if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();category=e.key==='Home'?0:e.key==='End'?3:(category+(e.key==='ArrowRight'?1:3))%4;$('#search').value='';renderTabs();renderResults();$('#tab-'+category).focus()}};node.append(b)});$('#results').setAttribute('aria-labelledby','tab-'+category)}
function renderResults(){const node=$('#results'),q=$('#search').value.trim().toLowerCase();node.replaceChildren();let count=0;categories[category].items.forEach(([name,en,note,slots],i)=>{const key=category+'-'+i;if(!(name+' '+en+' '+note).toLowerCase().includes(q)||onlyFavorites&&!favorites.has(key))return;count++;const card=el('article','card'),head=el('div','card-head'),b=el('button','expand'),title=el('div');title.append(el('strong','',name));if(en)title.append(el('small','',en));b.append(title,el('span','arrow',opened.has(key)?'−':'+'));b.setAttribute('aria-expanded',String(opened.has(key)));b.setAttribute('aria-controls','detail-'+key);b.onclick=()=>{opened.has(key)?opened.delete(key):opened.add(key);renderResults();node.querySelector('[aria-controls="detail-'+key+'"]').focus()};const star=el('button','star'+(favorites.has(key)?' on':''),favorites.has(key)?'★':'☆');star.setAttribute('aria-label',(favorites.has(key)?'移除常用：':'加入常用：')+name);star.setAttribute('aria-pressed',String(favorites.has(key)));star.onclick=()=>{favorites.has(key)?favorites.delete(key):favorites.add(key);renderResults()};head.append(b,star);const detail=el('div','detail');detail.id='detail-'+key;detail.hidden=!opened.has(key);detail.append(el('span','pending','待核對 · 不提供臨床數值'),el('p','',note),el('p','',applied?'目前套用：'+applied:'先在上方輸入並套用基本資料。'));const grid=el('div','slots');slots.forEach(label=>{const slot=el('div','slot');slot.append(el('b','',label),el('span','','— 待參考資料確認'));grid.append(slot)});detail.append(grid,el('div','source','來源：尚未提供 ｜ 本原型不執行劑量或器材計算'));const calculator=window.Infusion?.render(name,patient);if(calculator)detail.replaceChildren(calculator);card.append(head,detail);node.append(card)});if(!count)node.append(el('div','empty',onlyFavorites?'本分類沒有符合的常用項目。點 ☆ 可加入常用。':'沒有符合的項目，請換個關鍵字。'))}
$('#patient-form').onsubmit=e=>{e.preventDefault();const inputs=[...$('#patient-form').querySelectorAll('input')];const invalid=inputs.find(i=>!i.validity.valid||!Number.isFinite(i.valueAsNumber));const w=$('#weight'),weight=w.valueAsNumber;if(invalid){$('#error').textContent='請完整填寫數值，並確認各欄位的範圍。';invalid.focus();return}if(Math.abs(weight*10-Math.round(weight*10))>1e-7){$('#error').textContent='體重請以公斤輸入，最多一位小數。';w.focus();return}const age=[...$('#age-fields').querySelectorAll('input')].map(i=>i.previousElementSibling.textContent.replace(/\s+/g,'')+' '+i.value).join(' · ');applied=groups.find(g=>g[0]===group)[1]+' · '+age+' · '+weight.toFixed(1)+' kg';patient={group,weight,summary:applied};w.value=weight.toFixed(1);$('#summary').textContent=applied;$('#summary').className='summary ready';$('#error').textContent='';renderResults()};
$('#patient-form').addEventListener('input',markDirty);$('#search').oninput=renderResults;$('#favorites').onclick=()=>{onlyFavorites=!onlyFavorites;$('#favorites').classList.toggle('active',onlyFavorites);$('#favorites').setAttribute('aria-pressed',String(onlyFavorites));renderResults()};$('#reset').onclick=()=>{patient=null;group='child';$('#patient-form').reset();ageFields();renderGroups();applied=null;$('#summary').textContent='尚未套用基本資料';$('#summary').className='summary';$('#error').textContent='';renderResults()};renderGroups();ageFields();renderTabs();renderResults();
